changeSet.sql:
DO $$
DECLARE
    constraint_name text;
BEGIN
    -- Find and drop foreign key constraint on category_id if it exists
    SELECT conname INTO constraint_name
    FROM pg_constraint c
    JOIN pg_class t ON c.conrelid = t.oid
    JOIN pg_namespace n ON t.relnamespace = n.oid
    WHERE n.nspname = 'public'
      AND t.relname = 'category_item_mapping'
      AND c.contype = 'f'
      AND array_to_string(c.conkey, ',') = (
          SELECT array_to_string(array_agg(a.attnum), ',')
          FROM pg_attribute a
          WHERE a.attrelid = t.oid
            AND a.attname = 'category_id'
      );

    IF constraint_name IS NOT NULL THEN
        EXECUTE 'ALTER TABLE public.category_item_mapping DROP CONSTRAINT ' || constraint_name;
    END IF;
END;
$$;

DO $$
BEGIN
    IF EXISTS (
        SELECT 1 
        FROM information_schema.columns 
        WHERE table_schema = 'public' 
          AND table_name = 'category_item_mapping' 
          AND column_name = 'category_id'
    ) THEN
        ALTER TABLE public.category_item_mapping DROP COLUMN category_id;
    END IF;
END;
$$;
